begin;
do $$ declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();owner_id uuid;ids uuid[];test_item uuid;request uuid:=gen_random_uuid();token uuid;key_id uuid;before_count int;
begin
 select player_id into owner_id from public.player_badges where badge='APSU Founder' limit 1;
 insert into auth.users(id,raw_user_meta_data) values(u,'{}'),(v,'{}');
 insert into public.characters(id,player_id,world_id,slot,name,room_id) values(a,u,'alska-mogue',1,'Batch A','roomB'),(b,v,'alska-mogue',1,'Batch B','roomB');
 insert into public.chat_visits(id,player_id,character_id,world_id,room_id) values(gen_random_uuid(),u,a,'alska-mogue','roomB'),(gen_random_uuid(),v,b,'alska-mogue','roomB');
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 perform public.configure_room_door('alska-mogue','roomA','roomB',true);
 perform public.admin_spawn_items(request,'alska-mogue','roomB','key',2,'roomA');perform public.admin_spawn_items(request,'alska-mogue','roomB','key',2,'roomA');
 if (select count(*) from public.world_moderation where id=request and action='spawn_items')<>1 then raise exception 'Spawn audit/retry failed';end if;
 select array_agg(g.id order by g.id) into ids from public.ground_items g where g.key_room='roomA' and g.world_id='alska-mogue';
 if cardinality(ids)<>2 then raise exception 'Spawn duplicated';end if;
 perform set_config('request.jwt.claim.sub',u::text,true);
 foreach test_item in array ids loop perform public.inventory_action(gen_random_uuid(),a,test_item,'pickup');end loop;
 request:=gen_random_uuid();perform public.inventory_batch(request,a,ids,'give',b);perform public.inventory_batch(request,a,ids,'give',b);
 if (select count(*) from public.character_items where id=any(ids) and character_id=b)<>2 then raise exception 'Batch transfer failed';end if;
 begin perform public.inventory_batch(gen_random_uuid(),a,ids,'drop');raise exception 'Unavailable quantity allowed';exception when others then if sqlerrm<>'You do not have that quantity available' then raise;end if;end;
 begin perform public.save_character_location(a,'roomB','roomA');raise exception 'Locked movement allowed';exception when others then if sqlerrm<>'The door is locked' then raise;end if;end;
 if jsonb_array_length(public.room_snapshot(a)->'doors')<1 or jsonb_array_length(public.world_map('alska-mogue')->'doors')<1 then raise exception 'Door snapshot/map unavailable';end if;
 token:=public.acquire_door_use(a,'roomA');
 insert into public.character_items(character_id,kind,slot,key_room) values(a,'key',1,'roomC');
 begin perform public.change_door(a,'roomA',false,token,null,true);raise exception 'Wrong key worked';exception when others then if sqlerrm<>'A matching key is required' then raise;end if;end;
 perform public.release_lock_use(token);
 perform set_config('request.jwt.claim.sub',v::text,true);
 token:=public.acquire_door_use(b,'roomA');perform public.change_door(b,'roomA',false,token,null,true);
 perform public.save_character_location(b,'roomB','roomA');perform public.change_door(b,'roomA',true);
 perform set_config('request.jwt.claim.sub',u::text,true);token:=public.acquire_door_use(a,'roomA');
 perform set_config('request.jwt.claim.sub',v::text,true);perform public.change_door(b,'roomA',false);
 if exists(select 1 from public.lock_use l where l.door_id='roomA' and l.expires_at>clock_timestamp()) then raise exception 'Inside unlock did not release lease';end if;
 perform public.inventory_batch(gen_random_uuid(),b,ids,'drop');
 if exists(select 1 from public.character_items where id=any(ids)) then raise exception 'Batch drop failed';end if;
 foreach test_item in array ids loop perform public.inventory_action(gen_random_uuid(),b,test_item,'pickup');end loop;
 perform public.inventory_batch(gen_random_uuid(),b,ids,'delete');
 if exists(select 1 from public.character_items where id=any(ids)) then raise exception 'Batch delete failed';end if;
 begin perform public.admin_spawn_items(gen_random_uuid(),'alska-mogue','roomB','key',1,'roomA');raise exception 'Nonadmin spawned';exception when others then if sqlerrm<>'Admin permission required for this world' then raise;end if;end;
 -- A full recipient rolls back the entire batch, not just its final item.
 perform set_config('request.jwt.claim.sub',u::text,true);
 insert into public.character_items(character_id,kind,slot) values(a,'lockpick',1),(a,'lockpick',2),(b,'lockpick',1),(b,'lockpick',2);
 select array_agg(i.id order by i.id) into ids from public.character_items i where i.character_id=a and i.kind='lockpick';
 update public.characters set room_id='roomB' where id=b;
 update public.chat_visits set active=true,seen_at=clock_timestamp(),room_id='roomB' where character_id=b;
 begin perform public.inventory_batch(gen_random_uuid(),a,ids,'give',b);raise exception 'Over-capacity transfer allowed';exception when others then if sqlerrm<>'Their inventory limit is reached' then raise;end if;end;
 if (select count(*) from public.character_items i where i.character_id=a and i.id=any(ids))<>2 then raise exception 'Partial batch transfer';end if;
 if has_function_privilege('anon','public.inventory_batch(uuid,uuid,uuid[],text,uuid)','EXECUTE') then raise exception 'Anonymous batch allowed';end if;
end $$;
rollback;
select 'PASS: quantities, atomic transfers/retries, key targets, locked movement, inside unlock, spawn audit, permissions' as result;
